-- Answer length no longer gives the answer away (2026-10-19).
--
-- Before this, the correct choice was the longest of the three Standard
-- choices in 171 of 248 active questions, and the longest of the Difficult
-- set as presented in 148. Distractors were lengthened (and a few padded
-- correct answers trimmed) without changing any stem, correct fact or
-- citation. Tiers keep their meaning; every distractor stays wrong.
--
-- After: Standard, correct is longest in 66 and shortest in 63.
-- Difficult as presented by src/lib/difficulty.ts, longest in 42.
--
-- Applied live via SQL first. The pre-change rows are kept in
-- ltf.choices_backup_20261019 (RLS on, no anon/authenticated grants);
-- drop it once this has settled.

update ltf.choices c
set body = v.body, rationale = v.rationale
from (values
('036d141c-e561-4101-9c1b-13e801706ade', 'Lowering cumuliform clouds with heavy showers in a narrow band ahead of it', 'Warm fronts produce stratiform cloud over a wide area.'),
('04e306dc-02ca-4075-9d17-7f47c307933f', 'No; Part 107 requires a full 24 hours between drinking alcohol and flying', 'The bottle to throttle rule is 8 hours.'),
('061ffba0-5bd6-4bef-a277-a23d1d9b3440', 'The TFR applies; LAANC does not override it', NULL),
('07a50a3d-21a7-4a8b-8ce3-ba7a29ebe9c9', 'An emergency-only frequency monitored around the clock by Flight Service', 'CTAF is a routine advisory frequency, not an emergency channel.'),
('0819e6b4-5cd0-4929-b6bf-450b62c0bfdf', 'The crew must maintain effective communication at all times', NULL),
('081a3848-6363-4b90-9f2c-78ad1ec16c6c', 'It is acceptable as long as you feel no drowsiness an hour after the first dose', 'Impairment can be present without feeling it, and the illness itself matters.'),
('08e8d951-f940-4603-83e2-2d54422818ba', 'An annual inspection performed and signed off by an FAA-certificated mechanic', 'No annual inspection or mechanic requirement exists under Part 107.'),
('0ab64a85-2759-461a-a9db-a0856f50fc88', 'A frequency remote pilots use to request ATC clearance before launching', 'CTAF issues no clearances, and uncontrolled fields have no ATC to request one from.'),
('0ba20dcc-4e6a-49d0-a8cf-caf72ec19949', 'Only that the total remains under the 55 pound Part 107 limit', 'The regulatory limit is not the same as the aircraft''s structural and power limit.'),
('0d022c55-acba-48fa-842b-e6781f78a8d0', 'Lowering stratiform clouds and steady precipitation over a wide area', NULL),
('0e84e6eb-44da-42e8-9967-3de05ca5ef04', 'Automatic, permanent revocation of the remote pilot certificate', '107.59 allows denial for up to 1 year, or suspension or revocation. Nothing is automatic or permanent.'),
('0edaf1aa-d9f1-4161-9bfd-e3a063a5747d', 'Prior authorization from ATC under 107.41, requested through LAANC or DroneZone', '107.41 does not apply to Class G airspace.'),
('100a79c9-3765-4aa1-9e6b-dda3f8e8b511', 'Power lines generate strong magnetic fields that disable control and video links', 'The hazard is physical collision, not electromagnetic disabling.'),
('11e12bfc-35f5-4ef4-aa76-9add6b4efd2f', 'A private airfield that is closed to public use', 'Private fields carry an R symbol rather than a colour distinction.'),
('161a71dc-e44f-470a-a0f0-eab8ceee5be6', 'An observation of current conditions covering a 25 statute mile radius', 'A TAF forecasts rather than observes, and the radius is about 5 miles.'),
('16681cdf-edd0-43b1-ad45-cb3d74be8caa', 'The FAA''s acceptance letter, which must be carried during every flight over people', 'There is no requirement to carry an acceptance letter.'),
('17155cca-6c88-49be-a3eb-fd281273eed2', 'The local police department, after a permit application', 'Police do not control airspace.'),
('1785d9bc-2a0e-40dc-a0ff-a2ef4c9befce', 'It reports control station location, not takeoff location, and is VLOS only', 'That swaps them. A module reports the takeoff location; standard Remote ID reports the control station.'),
('183e2f9b-3a84-43d7-9e65-c0994c4715ea', 'It stays at 1 G in any coordinated turn, regardless of bank angle', 'Only straight and level flight is 1 G.'),
('1b4d4022-7694-49ec-8723-1346d95c09ec', 'Fully discharge each pack before recharging it to prevent memory effect', 'Deep discharge damages lithium chemistry; it is not a safety practice.'),
('1bf541d1-065d-462e-8bf7-99a6a15d27da', 'That it is secure and weighs less than 10 percent of the aircraft''s takeoff weight', 'There is no 10 percent rule. It must be secure and not affect flight characteristics or controllability.'),
('1bfcb371-36e2-4a74-887b-fb38994eb642', 'In a closed site with everyone on notice, or with no sustained flight over anyone', NULL),
('1d4bf7a8-8413-4596-be71-0d1ac81b4465', 'It satisfies the Part 107 requirement to keep a written risk assessment on file', 'Part 107 requires a preflight assessment but no written risk assessment document.'),
('1fdecf7e-abf3-4fdb-995f-24ac20cf360c', 'Obtain a night waiver under 107.200 and carry it during each night operation', 'Night waivers were eliminated in 2021.'),
('216d201e-b9d2-401d-b966-164818530539', 'Metal blocks the GPS satellite signals that the compass relies on for heading', 'The compass senses the magnetic field directly. GPS is separate.'),
('231e3031-c579-49d0-9150-b313a01fe69a', 'Magnetic interference rotates the aircraft heading shown on the controller', 'Compass interference is a separate issue from pilot orientation confusion.'),
