('9fdc17fb-aba1-46f0-8855-d62e8ba4bd12', 'None; Part 107 sets no fixed distance', NULL),
('a23f1434-bd27-478b-a35b-1410c88d5006', 'Recharge each pack immediately after landing, while it is still warm from flight', 'Charging a hot pack accelerates degradation and raises fire risk.'),
