('a2dcfebb-221c-47d4-b763-488b45e9f29d', 'Forecast cloud tops and turbulence for the next 24 hours', 'The analysis shows observations, not forecasts.'),
('a371ff04-53fb-4026-9cd4-e9946073706d', 'A rotating column of air extending from the base of a cloud to the ground', 'That describes a tornado.'),
